// Get the email ID from the loop
const emailData = $('Loop Over Emails').item.json;
const emailId = emailData.id;
const subject = emailData.subject || 'No Subject';

// Extract the classification from Ollama response
const response = $input.first().json.choices[0].message.content;

// Try multiple patterns to extract the label
let label = 'AI/Other';
const patterns = [
  /<output>(.*?)<\/output>/,
  /<o>(.*?)<\/o>/,
  /AI\/[A-Za-z]+/
];

for (const pattern of patterns) {
  const match = response.match(pattern);
  if (match) {
    label = match[1] || match[0];
    break;
  }
}

// Clean up label
label = label.trim();

return [{ 
  messageId: emailId,
  subject: subject,
  predicted_label: label,
  raw_response: response
}];

// Get the predicted label and message ID
const extractedData = $('Extract Label').item.json;
const messageId = extractedData.messageId;
const predictedLabel = extractedData.predicted_label;
const subject = extractedData.subject;

// Get all Gmail labels
const allLabels = $('Get All Gmail Labels').all();

// Find matching label ID
let labelId = null;
for (const label of allLabels) {
  if (label.json.name === predictedLabel) {
    labelId = label.json.id;
    break;
  }
}

if (!labelId) {
  console.log('Label not found for: ' + predictedLabel);
}

return [{
  messageId: messageId,
  subject: subject,
  predicted_label: predictedLabel,
  labelId: labelId
}];
